// Generate parameters respecting constraints: n > 0, diag is boolean
std::string buf = FUZZ_PARAM_STR();
size_t p = 0;
auto next_byte = [&](){ if (p >= buf.size()) p = 0; return static_cast<unsigned char>(buf[p++]); };
int n = static_cast<int>(next_byte() % 32u) + 1; // keep n in [1,32] to bound sizes
bool diag = (next_byte() & 1u) != 0;

// Invoke target function. No persistent objects to output; Eigen types are by value.
Eigen::SparseMatrix<double> D = cpp_duplication_matrix(n, diag);

// Basic sanity constraints only (exact layout not documented):
// Ensure sizes are non-zero and consistent with n being positive.
if (D.rows() <= 0 || D.cols() <= 0) { FUZZ_BAIL(); }
// Avoid expensive operations; just query lightweight properties.
volatile Eigen::Index nnz = D.nonZeros();
(void)nnz;

// Create a small symmetric matrix M (d x d) and a valid k in [1, d]
std::string buf = FUZZ_PARAM_STR();
size_t p = 0;
auto next_byte = [&](){ if (p >= buf.size()) p = 0; return static_cast<unsigned char>(buf[p++]); };
int d = static_cast<int>(next_byte() % 16u) + 1; // d in [1,16] to keep allocations small (~<= 2KB)
int k = static_cast<int>(next_byte() % d) + 1;   // k in [1,d]

Eigen::MatrixXd M(d, d);
// Fill upper triangle from buffer and mirror to enforce symmetry
for (int i = 0; i < d; ++i) {
    for (int j = i; j < d; ++j) {
        // Map byte to a small finite double in [-1,1]
        double v = (static_cast<int>(next_byte()) - 128) / 128.0;
        M(i, j) = v;
        M(j, i) = v;
    }
}

// Invoke the target function
auto result = cpp_k_eigh(M, k);
const Eigen::VectorXd &evals = std::get<0>(result);
const Eigen::MatrixXd &evecs = std::get<1>(result);

// Properties that should always hold:
// - eigenvalue vector length equals k
FUZZ_ASSERT(evals.size() == k, "cpp_k_eigh: eigenvalues length must equal k");
// Do light shape sanity on eigenvectors without assuming orientation:
if (!((evecs.rows() == d && evecs.cols() == k) || (evecs.rows() == k && evecs.cols() == d))) {
    // If orientation or layout is unexpected, bail to respect API constraints
    FUZZ_BAIL();
}
// Touch values lightly to ensure they are realized
volatile double touch = evals.size() > 0 ? evals[0] : 0.0; (void)touch;

// Generate a data matrix Y with at least 2 observations and finite entries
std::string buf = FUZZ_PARAM_STR();
size_t p = 0;
auto next_byte = [&](){ if (p >= buf.size()) p = 0; return static_cast<unsigned char>(buf[p++]); };
int r = static_cast<int>(next_byte() % 15u) + 2; // rows in [2,16]
int c = static_cast<int>(next_byte() % 16u) + 1; // cols in [1,16]
// Keep total elements <= 256 to bound allocations
if (r * c > 256) {
    c = std::max(1, 256 / r);
}
if (c <= 0) { FUZZ_BAIL(); }

Eigen::MatrixXd Y(r, c);
for (int i = 0; i < r; ++i) {
    for (int j = 0; j < c; ++j) {
        // Map bytes to small finite doubles to avoid Inf/NaN
        double v = (static_cast<int>(next_byte()) - 128) / 64.0; // ~[-2,2]
        Y(i, j) = v;
    }
}

// Invoke target function
Eigen::MatrixXd C = cpp_dcorr_matrix(Y);

// Expected properties (orientation may vary): output should be a square matrix
FUZZ_ASSERT(C.rows() == C.cols(), "cpp_dcorr_matrix: output must be square");
// Dimension should match either number of variables-as-columns or variables-as-rows
if (!(C.rows() == Y.cols() || C.rows() == Y.rows())) {
    FUZZ_BAIL();
}
// Light touch to ensure realization
volatile double d0 = C(0,0); (void)d0;
